pub const NAMES: [&str;6] = ["PERMIT","DENY","NOT_APPLICABLE","INDETERMINATE{D}","INDETERMINATE{P}","INDETERMINATE{DP}"];
            for &rule in &rules {
                let symbol = match &evaluation.records[rule] {
                    Some(Record::Evaluated {
                        outcome,..
                    }) => match outcome.decision.kind {
                        0 => 'P',1 => 'D',2 => '-',_ => 'I'
                    },_ => '.'
                };
                coverage[rule].push(symbol);
            }
